import java.util.*;

public class Main {
    static long comb(int n, int k) {
        if (n < k || k < 0) return 0;
        long rez = 1;
        for (int i = 0; i < k; i++) {
            rez = rez * (n - i) / (i + 1);
        }
        return rez;
    }

    // Safe access to precomputed arrays: return 0 if index out of bounds
    static long getRsc(long[] arr, int idx) {
        if (idx < 0 || idx >= arr.length) return 0;
        return arr[idx];
    }

    static class Pair {
        long sum;
        int cnt;
        Pair(long s, int c) { sum = s; cnt = c; }
        @Override
        public boolean equals(Object o) {
            if (o instanceof Pair) {
                Pair p = (Pair) o;
                return sum == p.sum && cnt == p.cnt;
            }
            return false;
        }
        @Override
        public int hashCode() {
            return Objects.hash(sum, cnt);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt();
        int c = sc.nextInt();
        sc.nextLine(); // consume newline
        String s = sc.next();
        int n = 2 * (r + c);
        long[] lsc = new long[62];
        long[] rsc = new long[62];
        long[] rsc2 = new long[62];
        lsc[2 * r - 1] = 1;
        for (int i = 2 * r; i < n; i++) {
            lsc[i] = lsc[i - 1] * i / (i - 2 * r + 1);
        }
        for (int i = 0; i <= n; i++) {
            rsc[i] = comb(i, r);
            rsc2[i] = comb(i, r - 1);
        }
        long nsum = rsc[n / 2] * rsc[n / 2];
        long msum = 0;
        int cnta = 0, cntb = 0;
        for (int i = n - 1; i >= 0; i--) {
            int ok;
            if (msum > 0) ok = 1;
            else ok = 0;
            if (cntb == n / 2) ok = 1;
            if (cnta == n / 2) ok = 0;
            if (ok == 1) {
                cnta++;
                msum = msum - rsc2[n / 2 - cnta] * rsc[n / 2 - cntb];
            } else {
                cntb++;
                msum = msum + rsc2[n / 2 - cntb] * rsc[n / 2 - cnta];
            }
        }
        msum = Math.max(msum, -msum);
        Map<Pair, Long> mm = new HashMap<>();
        mm.put(new Pair(0, 0), 1L);
        for (int i = n - 1; i >= 2 * r - 1; i--) {
            Map<Pair, Long> nm = new HashMap<>();
            for (Map.Entry<Pair, Long> entry : mm.entrySet()) {
                long sum = entry.getKey().sum;
                int cnt = entry.getKey().cnt;
                long ncnt = entry.getValue();
                int ast = n / 2 - cnt;
                int bst = i + 1 - ast;
                long asum = sum + getRsc(rsc2, ast - 1) * getRsc(rsc, bst);
                long bsum = sum - getRsc(rsc2, bst - 1) * getRsc(rsc, ast);
                char ch = s.charAt(i);
                if (ch == 'A') {
                    Pair p1 = new Pair(asum, cnt + 1);
                    nm.put(p1, nm.getOrDefault(p1, 0L) + ncnt);
                    Pair p2 = new Pair(bsum, cnt);
                    nm.put(p2, nm.getOrDefault(p2, 0L));
                } else if (ch == 'B') {
                    Pair p1 = new Pair(asum, cnt + 1);
                    nm.put(p1, nm.getOrDefault(p1, 0L));
                    Pair p2 = new Pair(bsum, cnt);
                    nm.put(p2, nm.getOrDefault(p2, 0L) + ncnt);
                } else { // '?'
                    Pair p1 = new Pair(asum, cnt + 1);
                    nm.put(p1, nm.getOrDefault(p1, 0L) + ncnt);
                    Pair p2 = new Pair(bsum, cnt);
                    nm.put(p2, nm.getOrDefault(p2, 0L) + ncnt);
                }
            }
            nsum = nsum - lsc[i];
            mm.clear();
            for (Map.Entry<Pair, Long> entry : nm.entrySet()) {
                long sum = entry.getKey().sum;
                int cnt = entry.getKey().cnt;
                long ncnt = entry.getValue();
                int ast = n / 2 - cnt;
                int bst = i - ast;
                if (cnt > n / 2 || (n - i - cnt) > n / 2) continue;
                long bound = msum + getRsc(rsc, ast) * getRsc(rsc, bst);
                if (sum < -bound || sum > bound) continue;
                Pair p = new Pair(sum, cnt);
                mm.put(p, mm.getOrDefault(p, 0L) + ncnt);
            }
        }
        long bsum = Long.MAX_VALUE;
        for (Map.Entry<Pair, Long> entry : mm.entrySet()) {
            long sum = entry.getKey().sum;
            bsum = Math.min(bsum, Math.max(sum, -sum));
        }
        long rasp = 0;
        for (Map.Entry<Pair, Long> entry : mm.entrySet()) {
            long sum = entry.getKey().sum;
            long ncnt = entry.getValue();
            int cnt = entry.getKey().cnt;
            if (sum == bsum || sum == -bsum) {
                int sem = 0;
                for (int i = 0; i < 2 * r - 1; i++) {
                    char ch = s.charAt(i);
                    if (ch == '?') sem++;
                    else if (ch == 'A') cnt++;
                }
                ncnt = ncnt * comb(sem, n / 2 - cnt);
                rasp += ncnt;
            }
        }
        System.out.println(rasp);
    }
}
